import { randomBytes } from "node:crypto";
import { existsSync } from "node:fs";
import { writeFile } from "node:fs/promises";

// Creates .env.local with random first-run passwords for local development. Never commit it.
if (existsSync(".env.local")) {
  console.log(".env.local already exists; leaving it untouched.");
  process.exit(0);
}
const secret = () => randomBytes(12).toString("base64url");
const lead = secret(), barista = secret();
await writeFile(".env.local", [
  "# Local development only. Generated by `pnpm setup:local`.",
  "DATABASE_URL=",
  "BOOTSTRAP_LEAD_USERNAME=lead",
  `BOOTSTRAP_LEAD_PASSWORD=${lead}`,
  "BOOTSTRAP_BARISTA_USERNAME=barista",
  `BOOTSTRAP_BARISTA_PASSWORD=${barista}`,
  `CRON_SECRET=${secret()}`,
  "",
].join("\n"), { mode: 0o600 });
console.log("Wrote .env.local. First-run accounts (created when the local database is empty):");
console.log(`  lead     / ${lead}`);
console.log(`  barista  / ${barista}`);
